import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import com.sun.net.httpserver.*;

public class ReportService {
    private static final String DB_URL = "jdbc:postgresql://localhost:5432/reports";
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final ExecutorService pool = Executors.newFixedThreadPool(4);

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/reports", ReportService::handleReports);
        server.createContext("/api/export", ReportService::handleExport);
        server.setExecutor(pool);
        server.start();
        System.out.println("Report service started on :8080");
    }

    static void handleReports(HttpExchange ex) throws IOException {
        if (!"GET".equals(ex.getRequestMethod())) {
            ex.sendResponseHeaders(405, 0); ex.close(); return;
        }
        Map<String, String> params = parseQuery(ex.getRequestURI().getQuery());
        String department = params.getOrDefault("dept", "engineering");
        String dateRange = params.getOrDefault("range", "30");
        String reportType = params.getOrDefault("type", "summary");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build query based on report type
            String query;
            if ("detail".equals(reportType)) {
                query = "SELECT r.id, r.title, r.created_at, u.email, r.content " +
                        "FROM reports r JOIN users u ON r.author_id = u.id " +
                        "WHERE r.department = '" + department + "' " +
                        "AND r.created_at > NOW() - INTERVAL '" + dateRange + " days' " +
                        "ORDER BY r.created_at DESC";
            } else {
                query = "SELECT department, COUNT(*) as cnt, MAX(created_at) as latest " +
                        "FROM reports WHERE department = '" + department + "' " +
                        "AND created_at > NOW() - INTERVAL '" + dateRange + " days' " +
                        "GROUP BY department";
            }

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);
            StringBuilder json = new StringBuilder("[");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",");
                json.append("{");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) json.append(",");
                    json.append("\"").append(meta.getColumnName(i)).append("\":");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("]");
            byte[] resp = json.toString().getBytes();
            ex.getResponseHeaders().set("Content-Type", "application/json");
            ex.sendResponseHeaders(200, resp.length);
            ex.getResponseBody().write(resp);
        } catch (SQLException e) {
            byte[] err = ("{\"error\":\"" + e.getMessage() + "\"}").getBytes();
            ex.sendResponseHeaders(500, err.length);
            ex.getResponseBody().write(err);
        }
        ex.close();
    }

    static void handleExport(HttpExchange ex) throws IOException {
        if (!"POST".equals(ex.getRequestMethod())) {
            ex.sendResponseHeaders(405, 0); ex.close(); return;
        }
        // Read body for export config
        String body = new String(ex.getRequestBody().readAllBytes());
        // Simple JSON field extraction (no library dependency)
        String filename = extractField(body, "filename");
        String query = extractField(body, "query");

        if (filename == null || query == null) {
            byte[] err = "{\"error\":\"missing fields\"}".getBytes();
            ex.sendResponseHeaders(400, err.length);
            ex.getResponseBody().write(err); ex.close(); return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);
            // Write CSV to /tmp/exports/
            File outFile = new File("/tmp/exports/" + filename);
            try (PrintWriter pw = new PrintWriter(outFile)) {
                ResultSetMetaData meta = rs.getMetaData();
                int cols = meta.getColumnCount();
                while (rs.next()) {
                    for (int i = 1; i <= cols; i++) {
                        if (i > 1) pw.print(",");
                        pw.print(rs.getString(i));
                    }
                    pw.println();
                }
            }
            byte[] resp = ("{\"file\":\"" + outFile.getAbsolutePath() + "\"}").getBytes();
            ex.getResponseHeaders().set("Content-Type", "application/json");
            ex.sendResponseHeaders(200, resp.length);
            ex.getResponseBody().write(resp);
        } catch (SQLException e) {
            byte[] err = ("{\"error\":\"" + e.getMessage() + "\"}").getBytes();
            ex.sendResponseHeaders(500, err.length);
            ex.getResponseBody().write(err);
        }
        ex.close();
    }

    static String extractField(String json, String field) {
        String key = "\"" + field + "\"";
        int idx = json.indexOf(key);
        if (idx < 0) return null;
        int colon = json.indexOf(':', idx + key.length());
        int quote1 = json.indexOf('"', colon + 1);
        int quote2 = json.indexOf('"', quote1 + 1);
        return json.substring(quote1 + 1, quote2);
    }

    static Map<String, String> parseQuery(String query) {
        Map<String, String> map = new HashMap<>();
        if (query == null) return map;
        for (String param : query.split("&")) {
            String[] kv = param.split("=", 2);
            if (kv.length == 2) {
                map.put(URLDecoder.decode(kv[0], java.nio.charset.StandardCharsets.UTF_8),
                        URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8));
            }
        }
        return map;
    }
}
